var controleCampo = 1;
function adicionarCampo(){
  controleCampo++;
  document.getElementById('formulario').insertAdjacentHTML('beforeend', '<div class="inputs" id="campo '+ controleCampo +'" ><label class="label">EMPRESA' + controleCampo + ': </label><input type="text" class="inputs2" name="gerente"/> <button type="button" onclick="removerCampo(' + controleCampo + ')"> - </button></div></div>');
}

