function maisCampo(){
  controleCampo++;
  document.getElementById('formulario').insertAdjacentHTML('beforeend', '<div class="inputs" id="Campo"><label class="label">RESPONSÁVEL '+controleCampo+': </label><input type="text" class="inputs2" name="codigo"/><button type="button" onclick="menosCampo('+controleCampo+')"> - </button></div>');
}

function menosCampo(idCampo){
  document.getElementById('Campo' + idCampo).remove();
}

function duplicarCampos(){
	var clone = document.getElementById('origem').cloneNode(true);
	var destino = document.getElementById('destino');
	destino.appendChild (clone);
	var camposClonados = clone.getElementsByTagName('input');
	
	for(i=0; i<camposClonados.length;i++){
		camposClonados[i].value = '';
	}
	
	
	
}

function removerCampos(id){
	var node1 = document.getElementById('destino');
	node1.removeChild(node1.childNodes[0]);
}
