function validarForm(){
	var pwd, pwd0;
	alert("funciono");
	pwd= document.getElementById("pwd");
	pwd0 = document.getElementById("pwd0");
	alert(pwd0.value);
	alert(pwd.value);
	if(pwd.value=="si" && !pwd0.value){
		alert("Por favor digitar la contraseña");
		pwd0.focus();
	}	
}
function Activar(){
	var sel = document.getElementById("pwd");
	var pwd = document.getElementById("pwd0");
	if(sel.value == "si"){
		pwd.disabled = false;
		pwd.focus();
	}else{
		pwd.value = "";
		pwd.disabled = true;
	}
}

window.onload = function(){
	var btnEnviar, seleccion, contraseña;
	btnEnviar = document.getElementById("btn_Enviar");
	seleccion =  document.getElementById("pwd");
	btnEnviar.onclick = validarForm;
	seleccion.onchange = Activar;
	contraseña.onblur = validarForm;
}


